#!/usr/bin/env python3
import seeed_mlx90640
from serial import Serial
import numpy as np
import cv2


class ThermalCamera:
    """!
    A class for interfacing with a thermal camera using I2C or Serial communication modes.
    """
    ## Constant representing the I2C communication mode
    I2C = 0  
    ## Constant representing the Serial communication mode
    SERIAL = 1
    ## Default communication mode is I2C  
    MODE = I2C  

    def __init__(self, port=None):
        """!
        Constructor for the ThermalCamera class.

        @param port<str>: The port for Serial communication. If None, defaults to I2C mode.
        """
        super(ThermalCamera, self).__init__()
        ## Counter for the number of frames captured
        self.frameCount = 0  

        # I2C mode
        if port is None:
            self.dataHandle = seeed_mlx90640.grove_mxl90640()  ## Initialize I2C data handler
            self.dataHandle.refresh_rate = seeed_mlx90640.RefreshRate.REFRESH_0_5_HZ
            self.readData = self.i2cRead  ## Set the data reading method to I2C
        else:
            self.MODE = ThermalCamera.SERIAL
            ## Serial port for communication
            self.port = port  
            self.dataHandle = Serial(self.port, 2000000, timeout=5)  ## Initialize Serial data handler
            self.readData = self.serialRead  ## Set the data reading method to Serial

    def i2cRead(self):
        """!
        Reads thermal data from the camera using I2C mode.

        @return list: A 24x32 2D list representing the thermal image, with normalized pixel values.
        """
        ti = []
        try:
            hetData = [0] * 768  ## Initialize the frame buffer for 24x32 thermal data
            while True:
                self.dataHandle.getFrame(hetData)
                if len(hetData) < 768 or float("nan") in hetData:
                    continue
                else:
                    break

            max_temp = max(hetData)  ## Maximum temperature in the frame
            thermal_image = [(item / max_temp) * 255 for item in hetData]  ## Normalize pixel values

            for line_number in range(24):
                ti.append(thermal_image[0 + 32 * line_number:32 + 32 * line_number])  ## Reshape into 24x32

        except Exception as e:
            print(f"ERROR: Thermal picture taking failed; {e}")
            ti = [[0] * 32] * 24  ## Return a blank image in case of an error

        return ti

    def serialRead(self):
        """!
        Reads thermal data from the camera using Serial mode.

        @return list: A list of temperature values read from the serial port.
        """
        hetData = self.dataHandle.read_until(terminator=b'\r\n')  ## Read serial data until newline
        hetData = str(hetData, encoding="utf8").split(",")  ## Decode and split the data
        hetData = hetData[:-1]  ## Remove any trailing empty values
        return hetData


